static class Credential implements Serializable {
    static final long serialVersionUID = 1L;
    String username;
    transient char[] secretKey;
    static final byte KEY = 0x5A;

    Credential(String username, char[] secretKey) { this.username = username; this.secretKey = secretKey; }

    private void writeObject(ObjectOutputStream out) throws IOException {
        out.defaultWriteObject();
        byte[] zaszyfrowane = new byte[secretKey.length];
        for (int i = 0; i < secretKey.length; i++) {
            zaszyfrowane[i] = (byte) (secretKey[i] ^ KEY);
        }
        out.writeObject(zaszyfrowane);
    }

    private void readObject(ObjectInputStream in) throws IOException, ClassNotFoundException {
        in.defaultReadObject();
        byte[] zaszyfrowane = (byte[]) in.readObject();
        secretKey = new char[zaszyfrowane.length];
        for (int i = 0; i < zaszyfrowane.length; i++) {
            secretKey[i] = (char) (zaszyfrowane[i] ^ KEY);
        }
    }
}

