static void printTransientFieldsAfterDeserialization(Object before, Object after) throws IllegalAccessException {
    for (Field f : before.getClass().getDeclaredFields()) {
        if (Modifier.isTransient(f.getModifiers())) {
            f.setAccessible(true);
            System.out.println(f.getName() + ": przed=" + f.get(before) + ", po=" + f.get(after));
        }
    }
}

static class CacheEntry implements Serializable {
    static final long serialVersionUID = 1L;
    String key, value;
    transient long lastAccessTimestamp;

    private void readObject(ObjectInputStream in) throws IOException, ClassNotFoundException {
        in.defaultReadObject();
        lastAccessTimestamp = System.currentTimeMillis();
    }
}

static List<CacheEntry> findStaleEntries(List<CacheEntry> entries, long maxAgeMillis) {
    long teraz = System.currentTimeMillis();
    return entries.stream()
        .filter(e -> teraz - e.lastAccessTimestamp > maxAgeMillis)
        .toList();
}

