static class SecureDocument implements Serializable {
    static final long serialVersionUID = 1L;
    transient String rawSecretContent;
    String encryptedContent;

    SecureDocument(String content) {
        this.rawSecretContent = content;
        this.encryptedContent = new StringBuilder(content).reverse().toString();
    }

    String decrypt() {
        return new StringBuilder(encryptedContent).reverse().toString();
    }
}

