static void auditClass(Class<?> clazz) {
    System.out.println("=== " + clazz.getSimpleName() + " ===");
    for (Field f : clazz.getDeclaredFields()) {
        int mods = f.getModifiers();
        System.out.printf("%-20s %-15s transient=%-5b static=%-5b%n",
            f.getName(), f.getType().getSimpleName(),
            Modifier.isTransient(mods), Modifier.isStatic(mods));
    }
}

